import{_ as p,a0 as o,w as r,s as d,ao as t,I as i,x as e,a1 as l,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"使用防火牆讓你的 Linux 更加強大 | LCTT x X-CMD","titleTemplate":false,"description":"使用防火牆讓你的 Linux 更加強大 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用防火牆讓你的 Linux 更加強大 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用防火牆讓你的 Linux 更加強大 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190702 Make Linux stronger with firewalls","title":"使用防火牆讓你的 Linux 更加強大","tag":"201907","desc":""},"relativePath":"201907/20190702 Make Linux stronger with firewalls.md","filePath":"[post].md"}'),u={name:"201907/20190702 Make Linux stronger with firewalls.md"};function g(h,s,k,b,f,c){const a=o("Link");return r(),d("div",null,[s[50]||(s[50]=t('<h1 id="使用防火牆讓你的-linux-更加強大" tabindex="-1">使用防火牆讓你的 Linux 更加強大 <a class="header-anchor" href="#使用防火牆讓你的-linux-更加強大" aria-label="Permalink to “使用防火牆讓你的 Linux 更加強大”">​</a></h1><blockquote><p>掌握防火牆的工作原理，以及如何設置防火牆來提高 Linux 的安全性</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201907/13/114424m9clibvi0p128fln.jpg" alt=""></p><p>所有人都聽説過防火牆（哪怕僅僅是在網絡犯罪片裏看到過相關的情節設定），很多人也知道他們的計算機裏很可能正運行着防火牆，但是很少有人明白在必要的時候如何駕馭防火牆。</p><p>防火牆被用來攔截那些不請自來的網絡流量，然而不同網絡需要的安全級別也不盡相同。比如説，和在外面一家咖啡館裏使用公共 WiFi 相比，你在家裏的時候可以更加信任網絡裏的其它計算機和設備。你或許希望計算機能夠區分可以信任和不可信任的網絡，不過最好還是應該學會自己去管理（或者至少是核實）你的安全設置。</p><h3 id="防火牆的工作原理" tabindex="-1">防火牆的工作原理 <a class="header-anchor" href="#防火牆的工作原理" aria-label="Permalink to “防火牆的工作原理”">​</a></h3>',6)),i("p",null,[s[1]||(s[1]=e("網絡裏不同設備之間的通信是通過一種叫做",-1)),s[2]||(s[2]=i("ruby",null,[e("端口"),i("rt",null,"port")],-1)),s[3]||(s[3]=e("的網關實現的。這裏的端口指的並不是像 USB 端口 或者 HDMI 端口這樣的物理連接。在網絡術語中，端口是一個純粹的虛擬概念，用來表示某種類型的數據到達或離開一台計算機時候所走的路徑。其實也可以換個名字來稱呼，比如叫“連接”或者“門口”，不過 ",-1)),l(a,{href:"https://tools.ietf.org/html/rfc793"},{default:n(()=>[...s[0]||(s[0]=[e("早在 1981 年的時候",-1)])]),_:1}),s[4]||(s[4]=e(" 它們就被稱作端口了，這個叫法也沿用至今。其實端口這個東西沒有任何特別之處，只是一種用來指代一個可能會發生數據傳輸的地址的方式。",-1))]),i("p",null,[s[6]||(s[6]=e("1972 年，發佈了一份 ",-1)),l(a,{href:"https://tools.ietf.org/html/rfc433"},{default:n(()=>[...s[5]||(s[5]=[e("端口號列表",-1)])]),_:1}),s[7]||(s[7]=e("（那時候的端口被稱為“",-1)),s[8]||(s[8]=i("ruby",null,[e("套接字"),i("rt",null,"socket")],-1)),s[9]||(s[9]=e("”），並且從此演化為一組眾所周知的標準端口號，幫助管理特定類型的網絡流量。比如説，你每天訪問網站的時候都會使用 80 和 443 端口，因為互聯網上的絕大多數人都同意（或者是默認）數據從 web 服務器上傳輸的時候是通過這兩個端口的。如果想要驗證這一點，你可以在使用瀏覽器訪問網站的時候在 URL 後面加上一個非標準的端口號碼。比如説，訪問 ",-1)),s[10]||(s[10]=i("code",null,"example.com:42",-1)),s[11]||(s[11]=e(" 的請求會被拒絕，因為 example.com 在 42 端口上並不提供網站服務。",-1))]),s[51]||(s[51]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/uploads/web-port-nonstandard.png",alt:"Navigating to a nonstandard port produces an error",title:"Navigating to a nonstandard port produces an error"})],-1)),s[52]||(s[52]=i("p",null,[e("如果你是通過 80 端口訪問同一個網站，就可以（不出所料地）正常訪問了。你可以在 URL 後面加上 "),i("code",null,":80"),e(" 來指定使用 80 端口，不過由於 80 端口是 HTTP 訪問的標準端口，所以你的瀏覽器其實已經默認在使用 80 端口了。")],-1)),s[53]||(s[53]=i("p",null,"當一台計算機（比如説 web 服務器）準備在指定端口接收網絡流量的時候，保持該端口向網絡流量開放是一種可以接受的（也是必要的）行為。但是不需要接收流量的端口如果也處在開放狀態就比較危險了，這就是需要用防火牆解決的問題。",-1)),s[54]||(s[54]=i("h4",{id:"安裝-firewalld",tabindex:"-1"},[e("安裝 firewalld "),i("a",{class:"header-anchor",href:"#安裝-firewalld","aria-label":"Permalink to “安裝 firewalld”"},"​")],-1)),i("p",null,[s[13]||(s[13]=e("有很多種配置防火牆的方式，這篇文章介紹 ",-1)),l(a,{href:"https://firewalld.org/"},{default:n(()=>[...s[12]||(s[12]=[e("firewalld",-1)])]),_:1}),s[14]||(s[14]=e("。在桌面環境下它被集成在",-1)),s[15]||(s[15]=i("ruby",null,[e("網絡管理器"),i("rt",null,"Network Manager")],-1)),s[16]||(s[16]=e("裏，在終端裏則是集成在 ",-1)),s[17]||(s[17]=i("code",null,"firewall-cmd",-1)),s[18]||(s[18]=e(" 裏。很多 Linux 發行版都預裝了這些工具。如果你的發行版裏沒有，你可以把這篇文章當成是管理防火牆的通用性建議，在你所使用的防火牆軟件裏使用類似的方法，或者你也可以選擇安裝 ",-1)),s[19]||(s[19]=i("code",null,"firewalld",-1)),s[20]||(s[20]=e("。",-1))]),s[55]||(s[55]=t(`<p>比如説在 Ubuntu 上，你必須啓用 universe 軟件倉庫，關閉默認的 <code>ufw</code> 防火牆，然後再安裝 <code>firewalld</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl disable ufw</span></span>
<span class="line"><span>$ sudo add-apt-repository universe</span></span>
<span class="line"><span>$ sudo apt install firewalld</span></span></code></pre></div><p>Fedora、CentOS、RHEL、OpenSUSE，以及其它很多發行版默認就包含了 <code>firewalld</code>。</p><p>無論你使用哪個發行版，如果希望防火牆發揮作用，就必須保持它在開啓狀態，並且設置成開機自動加載。你應該儘可能減少在防火牆維護工作上所花費的精力。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable --now firewalld</span></span></code></pre></div><h3 id="使用網絡管理器選擇區域" tabindex="-1">使用網絡管理器選擇區域 <a class="header-anchor" href="#使用網絡管理器選擇區域" aria-label="Permalink to “使用網絡管理器選擇區域”">​</a></h3><p>或許你每天都會連接到很多不同的網絡。在工作的時候使用的是一個網絡，在咖啡館裏是另一個，在家裏又是另一個。你的計算機可以判斷出哪一個網絡的使用頻率比較高，但是它並不知道哪一個是你信任的網絡。</p><p>一個防火牆的<ruby>區域<rt>zone</rt></ruby>裏包含了端口開放和關閉的預設規則。你可以通過使用區域來選擇一個對當前網絡最適用的策略。</p><p>你可以打開網絡管理器裏的連接編輯器（可以在應用菜單裏找到），或者是使用 <code>nm-connection-editor &amp;</code> 命令以獲取所有可用區域的列表。</p><p><img src="https://opensource.com/sites/default/files/uploads/nm-connection-editor.png" alt="Network Manager Connection Editor" title="Network Manager Connection Editor"></p><p>在網絡連接列表中，雙擊你現在所使用的網絡。</p><p>在出現的網絡配置窗口中，點擊“通用”標籤頁。</p><p>在“通用”面板中，點擊“防火牆區域”旁邊的下拉菜單以獲取所有可用區域的列表。</p><p><img src="https://opensource.com/sites/default/files/uploads/nm-zone.png" alt="Firewall zones" title="Firewall zones"></p><p>也可以使用下面的終端命令以獲取同樣的列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --get-zones</span></span></code></pre></div><p>每個區域的名稱已經可以透露出設計者創建這個區域的意圖，不過你也可以使用下面這個終端命令獲取任何一個區域的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --zone work --list-all</span></span>
<span class="line"><span>work</span></span>
<span class="line"><span>  target: default</span></span>
<span class="line"><span>  icmp-block-inversion: no</span></span>
<span class="line"><span>  interfaces:</span></span>
<span class="line"><span>  sources:</span></span>
<span class="line"><span>  services: ssh dhcpv6-client</span></span>
<span class="line"><span>  ports:</span></span>
<span class="line"><span>  protocols:</span></span>
<span class="line"><span>  [...]</span></span></code></pre></div><p>在這個例子中，<code>work</code> 區域的配置是允許接收 SSH 和 DHCPv6-client 的流量，但是拒絕接收其他任何用户沒有明確請求的流量。（換句話説，<code>work</code> 區域並不會在你瀏覽網站的時候攔截 HTTP 響應流量，但是 <strong>會</strong> 攔截一個針對你計算機上 80 端口的 HTTP 請求。）</p><p>你可以依次查看每一個區域，弄清楚它們分別都允許什麼樣的流量。比較常見的有：</p><ul><li><code>work</code>：這個區域應該在你非常信任的網絡上使用。它允許 SSH、DHCPv6 和 mDNS，並且還可以添加更多允許的項目。該區域非常適合作為一個基礎配置，然後在此之上根據日常辦公的需求自定義一個工作環境。</li><li><code>public</code>： 用在你不信任的網絡上。這個區域的配置和工作區域是一樣的，但是你不應該再繼續添加其它任何允許項目。</li><li><code>drop</code>： 所有傳入連接都會被丟棄，並且不會有任何響應。在不徹底關閉網絡的條件下，這已經是最接近隱形模式的配置了，因為只允許傳出網絡連接（不過隨便一個端口掃描器就可以通過傳出流量檢測到你的計算機，所以這個區域並不是一個隱形裝置）。如果你在使用公共 WiFi，這個區域可以説是最安全的選擇；如果你覺得當前的網絡比較危險，這個區域也一定是最好的選擇。</li><li><code>block</code>： 所有傳入連接都會被拒絕，但是會返回一個消息説明所請求的端口被禁用了。只有你主動發起的網絡連接是被允許的。這是一個友好版的 <code>drop</code> 區域，因為雖然還是沒有任何一個端口允許傳入流量，但是説明了會拒絕接收任何不是本機主動發起的連接。</li><li><code>home</code>： 在你信任網絡裏的其它計算機的情況下使用這個區域。該區域只會允許你所選擇的傳入連接，但是你可以根據需求添加更多的允許項目。</li><li><code>internal</code>： 和工作區域類似，該區域適用於內部網絡，你應該在基本信任網絡裏的計算機的情況下使用。你可以根據需求開放更多的端口和服務，同時保持和工作區域不同的一套規則。</li><li><code>trusted</code>： 接受所有的網絡連接。適合在故障排除的情況下或者是在你絕對信任的網絡上使用。</li></ul><h3 id="為網絡指定一個區域" tabindex="-1">為網絡指定一個區域 <a class="header-anchor" href="#為網絡指定一個區域" aria-label="Permalink to “為網絡指定一個區域”">​</a></h3><p>你可以為你的任何一個網絡連接都指定一個區域，並且對於同一個網絡的不同連接方式（比如以太網、WiFi 等等）也可以指定不同的區域。</p><p>選擇你想要的區域，點擊“保存”按鈕提交修改。</p><p><img src="https://opensource.com/sites/default/files/uploads/nm-set.png" alt="Setting a new zone" title="Setting a new zone"></p><p>養成為網絡連接指定區域的習慣的最好辦法是從你最常用的網絡開始。為你的家庭網絡指定家庭區域，為工作網絡指定工作區域，為你最喜歡的圖書館或者咖啡館的網絡指定公關區域。</p><p>一旦你為所有常用的網絡都指定了一個區域，在之後加入新的網絡的時候（無論是一個新的咖啡館還是你朋友家的網絡），試圖也為它指定一個區域吧。這樣可以很好地讓你意識到不同的網絡的安全性是不一樣的，你並不會僅僅因為使用了 Linux 而比任何人更加安全。</p><h3 id="默認區域" tabindex="-1">默認區域 <a class="header-anchor" href="#默認區域" aria-label="Permalink to “默認區域”">​</a></h3><p>每次你加入一個新的網絡的時候，<code>firewalld</code> 並不會提示你進行選擇，而是會指定一個默認區域。你可以在終端裏輸入下面這個命令來獲取你的默認區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --get-default</span></span>
<span class="line"><span>public</span></span></code></pre></div><p>在這個例子裏，默認區域是 <code>public</code> 區域。你應該保證該區域有非常嚴格的限制規則，這樣在將它指定到未知網絡中的時候才比較安全。或者你也可以設置你自己的默認區域。</p><p>比如説，如果你是一個比較多疑的人，或者需要經常接觸不可信任的網絡的話，你可以設置一個非常嚴格的默認區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --set-default-zone drop</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>$ sudo firewall-cmd --get-default</span></span>
<span class="line"><span>drop</span></span></code></pre></div><p>這樣一來，任何你新加入的網絡都會被指定使用 <code>drop</code> 區域，除非你手動將它制定為另一個沒有這麼嚴格的區域。</p><h3 id="通過開放端口和服務實現自定義區域" tabindex="-1">通過開放端口和服務實現自定義區域 <a class="header-anchor" href="#通過開放端口和服務實現自定義區域" aria-label="Permalink to “通過開放端口和服務實現自定義區域”">​</a></h3><p>Firewalld 的開發者們並不是想讓他們設定的區域能夠適應世界上所有不同的網絡和所有級別的信任程度。你可以直接使用這些區域，也可以在它們基礎上進行個性化配置。</p><p>你可以根據自己所需要進行的網絡活動決定開放或關閉哪些端口，這並不需要對防火牆有多深的理解。</p><h4 id="預設服務" tabindex="-1">預設服務 <a class="header-anchor" href="#預設服務" aria-label="Permalink to “預設服務”">​</a></h4><p>在你的防火牆上添加許可的最簡單的方式就是添加預設服務。嚴格來講，你的防火牆並不懂什麼是“服務”，因為它只知道端口號碼和使用協議的類型。不過在標準和傳統的基礎之上，防火牆可以為你提供一套端口和協議的組合。</p>`,39)),i("p",null,[s[22]||(s[22]=e("比如説，如果你是一個 web 開發者並且希望你的計算機對本地網絡開放（這樣你的同事就可以看到你正在搭建的網站了），可以添加 ",-1)),s[23]||(s[23]=i("code",null,"http",-1)),s[24]||(s[24]=e(" 和 ",-1)),s[25]||(s[25]=i("code",null,"https",-1)),s[26]||(s[26]=e(" 服務。如果你是一名遊戲玩家，並且在為你的遊戲公會運行開源的 ",-1)),l(a,{href:"https://www.mumble.com/"},{default:n(()=>[...s[21]||(s[21]=[e("murmur",-1)])]),_:1}),s[27]||(s[27]=e(" 語音聊天服務器，那麼你可以添加 ",-1)),s[28]||(s[28]=i("code",null,"murmur",-1)),s[29]||(s[29]=e(" 服務。還有其它很多可用的服務，你可以使用下面這個命令查看：",-1))]),s[56]||(s[56]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --get-services</span></span>
<span class="line"><span>    amanda-client amanda-k5-client bacula bacula-client \\</span></span>
<span class="line"><span>    bgp bitcoin bitcoin-rpc ceph cfengine condor-collector \\</span></span>
<span class="line"><span>    ctdb dhcp dhcpv6 dhcpv6-client dns elasticsearch \\</span></span>
<span class="line"><span>    freeipa-ldap freeipa-ldaps ftp [...]</span></span></code></pre></div><p>如果你找到了一個自己需要的服務，可以將它添加到當前的防火牆配置中，比如説：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-service murmur</span></span></code></pre></div><p>這個命令 <strong>在你的默認區域裏</strong> 添加了指定服務所需要的所有端口和協議，不過在重啓計算機或者防火牆之後就會失效。如果想讓你的修改永久有效，可以使用 <code>--permanent</code> 標誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-service murmur --permanent</span></span></code></pre></div><p>你也可以將這個命令用於一個非默認區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-service murmur --permanent --zone home</span></span></code></pre></div><h4 id="端口" tabindex="-1">端口 <a class="header-anchor" href="#端口" aria-label="Permalink to “端口”">​</a></h4><p>有時候你希望允許的流量並不在 <code>firewalld</code> 定義的服務之中。也許你想在一個非標準的端口上運行一個常規服務，或者就是想隨意開放一個端口。</p>`,9)),i("p",null,[s[32]||(s[32]=e("舉例來説，也許你正在運行開源的 ",-1)),l(a,{href:"https://opensource.com/article/18/5/maptool"},{default:n(()=>[...s[30]||(s[30]=[e("虛擬桌遊",-1)])]),_:1}),s[33]||(s[33]=e(" 軟件 ",-1)),l(a,{href:"https://github.com/RPTools"},{default:n(()=>[...s[31]||(s[31]=[e("MapTool",-1)])]),_:1}),s[34]||(s[34]=e("。由於 MapTool 服務器應該使用哪個端口這件事情並沒有一個行業標準，所以你可以自行決定使用哪個端口，然後在防火牆上“開一個洞”，讓它允許該端口上的流量。",-1))]),s[57]||(s[57]=t(`<p>實現方式和添加服務差不多：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-port 51234/tcp</span></span></code></pre></div><p>這個命令 <strong>在你的默認區域</strong> 裏將 51234 端口向 TCP 傳入連接開放，不過在重啓計算機或者防火牆之後就會失效。如果想讓你的修改永久有效，可以使用 <code>--permanent</code> 標誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-port 51234/tcp --permanent</span></span></code></pre></div><p>你也可以將這個命令用於一個非默認區域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-port 51234/tcp --permanent --zone home</span></span></code></pre></div><p>在路由器的防火牆上設置允許流量和在本機上設置的方式是不同的。你的路由器可能會為它的內嵌防火牆提供一個不同的配置界面（原理上是相同的），不過這就超出本文範圍了。</p><h3 id="移除端口和服務" tabindex="-1">移除端口和服務 <a class="header-anchor" href="#移除端口和服務" aria-label="Permalink to “移除端口和服務”">​</a></h3><p>如果你不再需要某項服務或者某個端口了，並且設置的時候沒有使用 <code>--permanent</code> 標誌的話，那麼可以通過重啓防火牆來清除修改。</p><p>如果你已經將修改設置為永久生效了，可以使用 <code>--remove-port</code> 或者 <code>--remove-service</code> 標誌來清除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --remove-port 51234/tcp --permanent</span></span></code></pre></div><p>你可以通過在命令中指定一個區域以將端口或者服務從一個非默認區域中移除。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --remove-service murmur --permanent --zone home</span></span></code></pre></div><h3 id="自定義區域" tabindex="-1">自定義區域 <a class="header-anchor" href="#自定義區域" aria-label="Permalink to “自定義區域”">​</a></h3><p>你可以隨意使用 <code>firewalld</code> 默認提供的這些區域，不過也完全可以創建自己的區域。比如如果希望有一個針對遊戲的特別區域，你可以創建一個，然後只有在玩兒遊戲的時候切換到該區域。</p><p>如果想要創建一個新的空白區域，你可以創建一個名為 <code>game</code> 的新區域，然後重新加載防火牆規則，這樣你的新區域就啓用了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --new-zone game --permanent</span></span>
<span class="line"><span>success</span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><p>一旦創建好並且處於啓用狀態，你就可以通過添加玩遊戲時所需要的服務和端口來實現個性化定製了。</p><h3 id="勤勉" tabindex="-1">勤勉 <a class="header-anchor" href="#勤勉" aria-label="Permalink to “勤勉”">​</a></h3><p>從今天起開始思考你的防火牆策略吧。不用着急，可以試着慢慢搭建一些合理的默認規則。你也許需要花上一段時間才能習慣於思考防火牆的配置問題，以及弄清楚你使用了哪些網絡服務，不過無論是處在什麼樣的環境裏，只要稍加探索你就可以讓自己的 Linux 工作站變得更為強大。</p><hr>`,21)),i("p",null,[s[36]||(s[36]=e("via: ",-1)),l(a,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:n(()=>[...s[35]||(s[35]=[e("https://opensource.com/article/19/7/make-linux-stronger-firewalls",-1)])]),_:1})]),i("p",null,[s[41]||(s[41]=e("作者：",-1)),l(a,{href:"https://opensource.com/users/seth"},{default:n(()=>[...s[37]||(s[37]=[e("Seth Kenlon",-1)])]),_:1}),s[42]||(s[42]=e(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[38]||(s[38]=[e("lujun9972",-1)])]),_:1}),s[43]||(s[43]=e(" 譯者：",-1)),l(a,{href:"https://github.com/chen-ni"},{default:n(()=>[...s[39]||(s[39]=[e("chen-ni",-1)])]),_:1}),s[44]||(s[44]=e(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:n(()=>[...s[40]||(s[40]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[47]||(s[47]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[45]||(s[45]=[e("LCTT",-1)])]),_:1}),s[48]||(s[48]=e(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:n(()=>[...s[46]||(s[46]=[e("Linux中國",-1)])]),_:1}),s[49]||(s[49]=e(" 榮譽推出",-1))])])}const C=p(u,[["render",g]]);export{x as __pageData,C as default};
